def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Find straight contiguous runs of 5s.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 5:
                c += 1
            if c - start >= 2:
                runs.append(("H", r, start, c - 1))

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == 5:
                r += 1
            if r - start >= 2:
                runs.append(("V", c, start, r - 1))

    for orient, fixed, lo, hi in runs:
        # Find colored components adjoining the run on either perpendicular side.
        starts = []
        if orient == "H":
            for c in range(lo, hi + 1):
                for rr in (fixed - 1, fixed + 1):
                    if 0 <= rr < h and grid[rr][c] not in (0, 5):
                        starts.append((rr, c))
        else:
            for r in range(lo, hi + 1):
                for cc in (fixed - 1, fixed + 1):
                    if 0 <= cc < w and grid[r][cc] not in (0, 5):
                        starts.append((r, cc))

        for sr, sc in starts:
            if (sr, sc) in seen:
                continue
            # Collect the connected colored seed pattern.
            stack = [(sr, sc)]
            comp = set()
            while stack:
                r, c = stack.pop()
                if (r, c) in comp or not (0 <= r < h and 0 <= c < w):
                    continue
                if grid[r][c] in (0, 5):
                    continue
                comp.add((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    stack.append((r + dr, c + dc))
            if not comp:
                continue
            seen.update(comp)
            rmin = min(r for r, c in comp)
            rmax = max(r for r, c in comp)
            cmin = min(c for r, c in comp)
            cmax = max(c for r, c in comp)

            if orient == "H":
                for r in range(rmin, rmax + 1):
                    for c in range(lo, hi + 1):
                        color = grid[rmin + (r - rmin) % (rmax - rmin + 1)][cmin]
                        if grid[r][c] == 0:
                            out[r][c] = color
            else:
                for r in range(lo, hi + 1):
                    for c in range(cmin, cmax + 1):
                        color = grid[rmin + (r - lo) % (rmax - rmin + 1)][c]
                        if grid[r][c] == 0:
                            out[r][c] = color

    return out
